command:example.dev:code:
if (Get-ChildItem -File | Any { $_.Length -gt 1GB }) {
    'At least one file is larger than 1 GB.'
}

$array = 1, 2, 'John'
if (-not ($array | All { $_ -is [int] })) {
    'At least one element is not an [int].'
}

$csv = @' "Id","Name","Job" "1","John","The Guy" "1","John","The Guy?" "2","Jane","[redacted]" '@ | ConvertFrom-Csv
$equality = { $left.Id -eq $right.Id -and $left.Name -eq $right.Name } $hashCode = { # -eq ignores case, so the hash code has to ignore case as well. "$($_.Id)|$($_.Name.ToUpperInvariant())".GetHashCode() }
$set = $csv | New-HashSet -EqualityScript $equality -HashCodeScript $hashCode $set.Count # 2

$people = @(
    [pscustomobject]@{ Name = 'Ann'; Age = 30 }
    [pscustomobject]@{ Name = 'Bob'; Age = 20 }
    [pscustomobject]@{ Name = 'Jim'; Age = 30 }
)
$byAge = { $x.Age.CompareTo($y.Age) }
$set = $people | New-SortedSet -ComparingScript $byAge
$set.Name -join ', '   # Bob, Ann

$byId = @{
    EqualityScript = { $x.Id -eq $y.Id }
    HashCodeScript = { $_.Id.GetHashCode() }
}
$dict = New-Dictionary @byId
$dict.Add([pscustomobject]@{ Id = 1; Name = 'first' }, 'a')
$dict.Add([pscustomobject]@{ Id = 1; Name = 'second' }, 'b')
# Error, because the dictionary already holds a key whose Id is 1

$people = @(
    [pscustomobject]@{ Id = 1; Name = 'John'; Dept = 'IT' }
    [pscustomobject]@{ Id = 2; Name = 'Jane'; Dept = 'HR' }
    [pscustomobject]@{ Id = 3; Name = 'Jim'; Dept = 'IT' }
)
$byId = $people | ConvertTo-Dictionary -KeyPropertyName Id
$byId[2].Name   # Jane
